flow.typescript:
// D21 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_flow.ts   (모델·마이크·인터넷 불필요)
//   [대체 경로] STT·LLM·TTS 모델 대신 글자 수·토큰 수로 걸리는 시간을 계산하는 규칙 함수를 쓴다.
const END = /[.!?。…~]+\s/;
const BUDGET: Record<string, number> = { endpoint: 0.5, stt: 0.3, llm: 0.5, tts: 0.2 };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function tokens(text: string): number {
  return Math.max(1, Math.floor(text.length / 2)); // 2글자 = 1토큰 어림
}

function splitSentences(text: string): string[] {
  const out: string[] = [];
  let buf = text + " ";
  let m: RegExpExecArray | null;
  while ((m = END.exec(buf)) !== null) {
    const cut = m.index + m[0].length;
    out.push(buf.slice(0, cut).trim());
    buf = buf.slice(cut);
  }
  return out;
}

function turnTime(reply: string, speechSec: number = 2, silenceMs: number = 500, stream: boolean = false): Record<string, number> {
  const ttft = 0.2;
  const tps = 30;
  const first = stream ? splitSentences(reply)[0] : reply; // v2는 첫 문장만 기다린다
  const t: Record<string, number> = {
    endpoint: silenceMs / 1000 + 0.03,
    stt: 0.15 + 0.05 * speechSec,
    llm: ttft + tokens(first) / tps,
    tts: 0.05 + 0.01 * first.length,
  };
  t.v2v = t.endpoint + t.stt + t.llm + t.tts;
  return t;
}

function pct(xs: number[], p: number): number {
  const k = ((xs.length - 1) * p) / 100;
  const lo = Math.floor(k);
  const hi = Math.min(lo + 1, xs.length - 1);
  return xs[lo] + (xs[hi] - xs[lo]) * (k - lo);
}

const REPLY = "내일 서울은 맑아요. 낮 최고 기온은 18도예요. 우산은 필요 없어요.";
const v1 = turnTime(REPLY);
const v2 = turnTime(REPLY, 2, 500, true);
const total = Object.values(BUDGET).reduce((a, b) => a + b, 0);
console.log(`v1 ${v1.v2v.toFixed(2)}초 → v2 ${v2.v2v.toFixed(2)}초 (예산 합계 ${total.toFixed(2)}초)`);
check(v2.v2v < v1.v2v && splitSentences(REPLY).length === 3, "v2(스트리밍)는 첫 문장만 기다려서 v1보다 빨라야 해요.");

const runs = [1, 1.5, 2, 2.5, 3, 4].map((s) => turnTime(REPLY, s, 500, true).v2v).sort((a, b) => a - b);
const p50 = pct(runs, 50);
const p95 = pct(runs, 95);
console.log(`p50 ${p50.toFixed(2)}초 · p95 ${p95.toFixed(2)}초`);
check(p50 <= p95 && p95 <= runs[runs.length - 1], "p95는 p50 이상, 최댓값 이하입니다.");

arch.typescript:
// D21 · Part 6 · Cascade vs S2S 구조 비교 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_arch.ts   (점수는 수업 토론용 상대 점수)
type Pts = Record<string, number>;
const ARCH: Record<string, Pts> = {
  "Cascade (로컬)": { 지연: 2, 감정: 1, 디버깅: 5, 도구: 5, 한국어: 4, 비용: 4, 개인정보: 5 },
  "Cascade (API)": { 지연: 3, 감정: 2, 디버깅: 5, 도구: 5, 한국어: 5, 비용: 3, 개인정보: 2 },
  "S2S (API)": { 지연: 5, 감정: 5, 디버깅: 2, 도구: 3, 한국어: 3, 비용: 2, 개인정보: 2 },
};
const CLINIC: Pts = { 지연: 0, 감정: 0, 디버깅: 3, 도구: 3, 한국어: 3, 비용: 0, 개인정보: 3 }; // 병원 예약 콜센터 가정

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function total(weights: Pts, pts: Pts): number {
  return Object.keys(weights).reduce((s, k) => s + weights[k] * pts[k], 0); // 가중치 × 점수
}

const scores: Record<string, number> = {};
for (const [name, pts] of Object.entries(ARCH)) scores[name] = total(CLINIC, pts);
for (const [name, s] of Object.entries(scores)) console.log(`${name.padEnd(16)} ${s}점`);
const names = Object.keys(scores);
const best = names.reduce((a, b) => (scores[b] > scores[a] ? b : a)); // 점수로 비교 (이름순이 아님)
console.log("선택:", best);
check(best === "Cascade (로컬)" && [...names].sort().pop() !== best, "이름순이 아니라 점수로 비교해야 해요.");

budget.typescript:
// D21 · Part 3 · 예산 설계기 (Latency Budget) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_budget.ts   (측정값은 코드 안의 모의 숫자)
const BUDGET: Record<string, number> = { endpoint: 0.5, stt: 0.3, llm: 0.5, tts: 0.2 };
const MEASURED: Record<string, number> = { endpoint: 0.53, stt: 0.28, llm: 0.71, tts: 0.16 }; // 모의 측정 p50

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const sum = (o: Record<string, number>): number => Object.values(o).reduce((a, b) => a + b, 0);
const TOTAL = sum(BUDGET);
console.log(`예산 합계 ${TOTAL.toFixed(2)}초 · 측정 합계 ${sum(MEASURED).toFixed(2)}초`);
const keys = Object.keys(BUDGET);
const over = keys.filter((k) => MEASURED[k] > BUDGET[k]);
for (const k of keys) {
  console.log(`${k.padEnd(9)} 예산 ${BUDGET[k].toFixed(2)} 측정 ${MEASURED[k].toFixed(2)} ${over.includes(k) ? "넘침" : "OK"}`);
}
const slack = (k: string): number => BUDGET[k] - MEASURED[k];
const worst = keys.reduce((a, b) => (slack(b) < slack(a) ? b : a)); // 예산을 가장 크게 넘긴 단계
console.log("가장 먼저 줄일 곳:", worst);
check(Math.abs(TOTAL - 1.5) < 1e-9 && over.join() === "endpoint,llm" && worst === "llm", "넘친 단계는 endpoint와 llm, 최악은 llm입니다.");

pipeline.typescript:
// D21 · Part 2·4 · v1 vs v2 타임라인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_pipeline.ts   (LLM 토큰이 일정 속도로 나온다고 보는 모의 스트림)
const END = /[.!?。…~]+\s/;
const MIN_CHARS = 8;
const TPS = 30; // 모의 LLM 속도: 초당 30토큰

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Piece = { t: number; text: string };

function* stream(text: string): Generator<Piece> {
  // 2글자 = 1토큰으로 보고 (시각, 글 조각)을 차례로 내준다 — 토큰 스트리밍 흉내
  let t = 0.2; // 첫 토큰까지(TTFT)
  for (let i = 0; i < text.length; i += 2) {
    yield { t, text: text.slice(i, i + 2) };
    t += 1 / TPS;
  }
}

function sentences(pieces: Iterable<Piece>): Piece[] {
  const out: Piece[] = [];
  let buf = "";
  for (const p of pieces) {
    buf += p.text;
    for (;;) {
      const m = END.exec(buf.slice(MIN_CHARS)); // 너무 짧은 조각('네.')은 따로 보내지 않음
      if (m === null) break;
      const cut = MIN_CHARS + m.index + m[0].length;
      out.push({ t: p.t, text: buf.slice(0, cut).trim() });
      buf = buf.slice(cut);
    }
  }
  return out;
}

const REPLY = "네, 알겠어요. 회의를 세 시 반으로 옮겼어요. 다른 일정도 확인해 드릴까요? ";
const chunks = sentences(stream(REPLY));
for (const c of chunks) console.log(`${c.t.toFixed(2)}초 첫 소리 가능 → '${c.text}'`);
const v1Start = 0.2 + Math.floor(REPLY.length / 2) / TPS; // v1: 답 전체가 끝나야 TTS 시작
const v2Start = chunks[0].t; // v2: 첫 문장이 완성되는 즉시 TTS 시작
console.log(`TTS 시작 v1 ${v1Start.toFixed(2)}초 · v2 ${v2Start.toFixed(2)}초 · 줄어든 시간 ${(v1Start - v2Start).toFixed(2)}초`);
check(chunks.length === 2 && v2Start < v1Start, "문장이 2조각으로 잘리고(짧은 '네.'는 합쳐짐), v2가 더 일찍 말하기 시작해야 해요.");

vad.typescript:
// D21 · Part 5 · VAD 말 끝 감지 (침묵 기준) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_vad.ts
//   [대체 경로] Silero VAD 대신 '32ms 프레임의 소리 크기(RMS)가 문턱보다 큰가'로 말/침묵을 가르는 간단한 VAD.
//   말소리 대신 사인파 두 토막(사이에 0.6초 쉼)을 합성해 쓴다.
const SR = 16000;
const CHUNK = 512; // 한 프레임 = 32ms

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function burst(sec: number, freq: number): number[] {
  return Array.from({ length: Math.floor(sec * SR) }, (_, i) => 0.3 * Math.sin((2 * Math.PI * freq * i) / SR));
}

function silence(sec: number): number[] {
  return new Array(Math.floor(sec * SR)).fill(0);
}

function endpoint(y: number[], minSilenceMs: number): number | null {
  // 말이 한 번 시작된 뒤 침묵이 minSilenceMs 이상 이어지면 '말 끝'을 알린 시각(초)
  let quiet = 0;
  let speaking = false;
  for (let i = 0; i + CHUNK <= y.length; i += CHUNK) {
    let e = 0;
    for (let j = i; j < i + CHUNK; j++) e += y[j] * y[j];
    const rms = Math.sqrt(e / CHUNK);
    if (rms > 0.05) {
      speaking = true;
      quiet = 0;
    } else if (speaking) {
      quiet += (CHUNK / SR) * 1000;
      if (quiet >= minSilenceMs) return (i + CHUNK) / SR;
    }
  }
  return null;
}

const y = [...silence(0.8), ...burst(0.8, 220), ...silence(0.6), ...burst(0.8, 180), ...silence(2)];
const trueEnd = (y.length - 2 * SR) / SR; // 실제로 말이 끝난 시각
const cuts: boolean[] = [];
for (const ms of [200, 300, 500, 800, 1000]) {
  const det = endpoint(y, ms);
  const cut = det !== null && det < trueEnd - 0.3; // 실제 끝보다 한참 일찍 판정 = 말 잘림
  cuts.push(cut);
  console.log(`침묵 기준 ${String(ms).padStart(4)}ms → 판정 ${det?.toFixed(2)}초 · ${cut ? "말 잘림" : "끝까지 기다림"}`);
}
check(cuts.join() === "true,true,true,false,false", "쉼(0.6초)보다 짧은 기준(500ms 이하)은 말을 자릅니다.");

turn.typescript:
// D21 · Part 5 · 턴 테이킹 (끼어듦 vs 늦은 대답) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_turn.ts
//   [대체 경로] 사람 대화 대신 '말 도중 쉼 길이' 표본을 코드에 적어 두고 침묵 기준별 결과를 센다.
const PAUSES_MS = [150, 250, 400, 650, 300, 900, 200, 500, 700, 350]; // 한 문장 안에서 쉬는 길이(모의 표본)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function evaluate(thresholdMs: number): { 기준: number; 끼어듦: number; 추가_기다림_ms: number } {
  const cuts = PAUSES_MS.filter((p) => p >= thresholdMs).length; // 쉼이 기준 이상이면 비서가 먼저 끼어든다
  return { 기준: thresholdMs, 끼어듦: cuts, 추가_기다림_ms: thresholdMs }; // 모든 턴이 기준만큼 늦어짐
}

const table = [200, 400, 700, 1000].map(evaluate);
for (const r of table) console.log(r);
check(table.map((r) => r.끼어듦).join() === "9,5,2,0" && table[0].추가_기다림_ms < table[3].추가_기다림_ms, "기준이 짧으면 끼어듦이 늘고, 길면 모든 턴이 늦어져요.");

pct.typescript:
// D21 · Part 3 · p50 · p95 읽기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_pct.ts   (지연 표본은 씨앗 고정 난수로 합성)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function percentile(xs: number[], p: number): number {
  // 선형 보간 백분위수(numpy 기본 방식과 같음)
  const s = [...xs].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  const hi = Math.min(lo + 1, s.length - 1);
  return s[lo] + (s[hi] - s[lo]) * (k - lo);
}

const rnd = mulberry32(7);
const v2v = [...Array.from({ length: 18 }, () => 1 + rnd() * 0.3), 2.4, 2.9]; // 대부분 1.0~1.3초, 가끔 아주 느린 턴 2개
const p50 = percentile(v2v, 50);
const p95 = percentile(v2v, 95);
const mean = v2v.reduce((a, b) => a + b, 0) / v2v.length;
console.log(`평균 ${mean.toFixed(2)}초 · p50 ${p50.toFixed(2)}초 · p95 ${p95.toFixed(2)}초 · 최대 ${Math.max(...v2v).toFixed(2)}초`);
check(p50 < mean && mean < p95 && percentile([1, 2, 3, 4, 5], 50) === 3 && percentile([0, 10], 95) === 9.5, "느린 꼬리가 평균은 끌어올리지만 p50은 거의 안 움직여요. p95로 꼬리를 봅니다.");

length.typescript:
// D21 · Part 3-1 · 답 길이 = 지연 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_length.ts   (모델 없이 'LLM 시간 = 첫 토큰 + 토큰 수 ÷ 초당 토큰' 식으로 계산)
const TTFT = 0.2;
const TPS = 30; // 모의 LLM: 첫 토큰 0.2초, 초당 30토큰

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const tokens = (text: string): number => Math.max(1, Math.floor(text.length / 2)); // 2글자 = 1토큰 어림
const llmSeconds = (text: string): number => TTFT + tokens(text) / TPS;

const SHORT = "내일 서울은 맑고 최고 18도예요."; // 음성용 짧은 지시를 받은 답
const LONG =
  "내일 서울의 날씨는 대체로 맑겠습니다. 아침 최저 기온은 9도, 낮 최고 기온은 18도로 일교차가 큽니다. " +
  "미세먼지는 보통 수준이며, 자외선 지수는 중간입니다. 가벼운 겉옷을 챙기시면 좋겠습니다. 우산은 필요하지 않습니다."; // 글 채팅용
for (const [name, text] of [["음성용", SHORT], ["글 채팅용", LONG]]) {
  console.log(`${name.padEnd(6)} 토큰 ${String(tokens(text)).padStart(3)} → LLM ${llmSeconds(text).toFixed(2)}초`);
}
check(llmSeconds(LONG) > 2 * llmSeconds(SHORT) && tokens(LONG) / tokens(SHORT) > 4, "토큰이 4배 이상 늘면 시간도 크게 늘어요.");

choose.typescript:
// D21 · Part 6 · 아키텍처 선택기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d21_choose.ts   (점수·가중치는 수업 토론용 상대 값)
type Pts = Record<string, number>;
const ARCH: Record<string, Pts> = {
  "Cascade (로컬)": { 지연: 2, 감정: 1, 디버깅: 5, 도구: 5, 한국어: 4, 비용: 4, 개인정보: 5 },
  "Cascade (API)": { 지연: 3, 감정: 2, 디버깅: 5, 도구: 5, 한국어: 5, 비용: 3, 개인정보: 2 },
  "S2S (API)": { 지연: 5, 감정: 5, 디버깅: 2, 도구: 3, 한국어: 3, 비용: 2, 개인정보: 2 },
};
const SCENARIOS: Record<string, Pts> = {
  "병원 예약 콜센터": { 지연: 2, 감정: 1, 디버깅: 3, 도구: 3, 한국어: 3, 비용: 2, 개인정보: 3 },
  "외국어 회화 튜터": { 지연: 3, 감정: 3, 디버깅: 1, 도구: 0, 한국어: 1, 비용: 2, 개인정보: 1 },
  "어르신 말벗": { 지연: 2, 감정: 3, 디버깅: 2, 도구: 1, 한국어: 3, 비용: 1, 개인정보: 3 },
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function choose(weights: Pts): [string, Record<string, number>] {
  const scores: Record<string, number> = {};
  for (const [name, pts] of Object.entries(ARCH)) scores[name] = Object.keys(weights).reduce((s, k) => s + weights[k] * pts[k], 0);
